def is_balanced(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    stack = []
    for c in s:
        if c in OPEN:
            stack.append(c)
        elif c in CLOSE:
            if not stack or stack.pop() != PAIRS[c]:
                return False
    return not stack

