from brackets import is_balanced, is_bracket

balanced = ['', '()', '[]', '{}', '()[]{}', '([{}])', '(a[b]{c})', 'f(x[0], y[1])', '((()))', '{[]}[()]', 'abc 123 ☃ !', '"["', '\\()']
unbalanced = ['(', ')', '([)]', '(]', '{[}', '())', '()(', ')(', '][']
for s in balanced:
    assert is_balanced(s) is True, s
for s in unbalanced:
    assert is_balanced(s) is False, s
